{
  "API_calls": [],
  "collected_information": {
    "environment": {
      "python_version": ">=3.9 and <3.12",
      "installation_commands": [
        "pip install --upgrade metagpt",
        "pip install --upgrade git+https://github.com/geekan/MetaGPT.git",
        "pip install -e .[test]"
      ],
      "config_file": "~/.metagpt/config2.yaml",
      "dependencies": {
        "requirements.txt": [
          "aiohttp==3.8.6",
          "pandas==2.1.1",
          "scikit_learn==1.3.2",
          "redis ~=5.0.0",
          "...other dependencies pinned or ranged versions..."
        ]
      }
    },
    "test_execution": {
      "ci_files": [".github/workflows/unittest.yaml", ".github/workflows/fulltest.yaml"],
      "os": "ubuntu-latest",
      "python_version_for_ci": "3.9",
      "env_vars": {
        "ALLOW_OPENAI_API_CALL": "0"
      },
      "install_steps": [
        "pip install -e .[test]",
        "npm install -g @mermaid-js/mermaid-cli",
        "playwright install --with-deps"
      ],
      "test_run": "pytest --continue-on-collection-errors tests/",
      "pytest_options": [
        "--ignore tests/metagpt/roles/main_chains/test_taskai.py",
        "--ignore tests/metagpt/roles/main_chains/test_taskmsg.py",
        "--doctest-modules",
        "--cov=metagpt",
        "--cov-report=xml",
        "--cov-report=html",
        "--durations=10"
      ],
      "output": "unittest.txt",
      "coverage_report": "coverage report -m",
      "failure_detection": "CI job fails if any tests fail as parsed from unittest.txt",
      "artifact_upload": ["test logs", "coverage reports", "uploaded to Codecov in fulltest.yaml"]
    },
    "notes": "No CONTRIBUTING.md file found. The environment and test info fully satisfy the requirements for the test file tests/metagpt/roles/test_researcher.py."
  },
  "terminate": true
}
